Method.Implementation:
///Get the Filename from the input stream
Set tSource = pInput.Attributes("Filename")
///Wrap the Stream object to StreamContainer	
set pInput = $classmethod(..#CONTAINERCLASS,"%New",pInput)
/// If the adapter has a value for ArchivePath, send async; otherwise send synchronously
/// to ensure that we don't return to the Adapter and let it delete the file before the
/// target Config Item is finished processing it. 
Set tWorkArchive=(""'=..Adapter.ArchivePath) 

Set currentDate = $ZDATETIME($ZTIMESTAMP,3,3)
Set extractDate =  $EXTRACT(currentDate,0,11)
Set extractTime = $EXTRACT(currentDate,11,$LENGTH(currentDate))

do ..valueToBeReplaced.SetAt(tSource,"%FN")
do ..valueToBeReplaced.SetAt(extractDate,"%CD")
do ..valueToBeReplaced.SetAt(extractTime,"%CT")	

//Replace the respective values in the Email subject and the body like Filename, Date / Time received 
Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject)
Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody)

$$$TRACE("Sending alert for successful file transfer.")
do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody)


For iTarget=1:1:1 { 
	Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W")
	If tWorkArchive {			
		Set tSC=..SendRequestAsync(tOneTarget,pInput)					
	}		
	Else {
		#; If not archiving send Sync to avoid Adapter deleting file before Operation gets it
		Set tSC=..SendRequestSync(tOneTarget,pInput)
	}			 
}	 


Quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
